BEGIN;SET search_path=labassist_student,public;
\ir ../../remaining-data/tests/helpers.sql
SELECT pg_temp.ok('AI seed contains context and queued work, not fabricated outputs',(SELECT count(*)=1 FROM ai_jobs WHERE status='QUEUED') AND NOT EXISTS(SELECT 1 FROM ai_messages WHERE role='ASSISTANT') AND NOT EXISTS(SELECT 1 FROM ai_project_designs));
CREATE TEMP TABLE seed_claim AS SELECT claim_ai_job('acceptance-seed-worker') AS data;
SELECT fail_ai_job((data->>'id')::uuid,(data->>'claim_token')::uuid,'Fixture removed from queue within rollback-only test') FROM seed_claim;
INSERT INTO ids SELECT 'thread',create_ai_conversation(owner,'Test project context',project) FROM f;
SELECT pg_temp.reject('AI threads are initially private',$q$SELECT read_ai_conversation(teammate,(SELECT id FROM ids WHERE key='thread')) FROM f$q$,'access denied');
SELECT pg_temp.reject('supervisor cannot read student AI conversations',$q$SELECT read_ai_conversation(supervisor,(SELECT id FROM ids WHERE key='thread')) FROM f$q$,'access denied');
SELECT append_ai_message(owner,(SELECT id FROM ids WHERE key='thread'),0,'71000000-0000-4000-8000-000000000001','Explain my sensor prototype.') FROM f;
SELECT pg_temp.ok('student-message retry is idempotent',(SELECT append_ai_message(owner,(SELECT id FROM ids WHERE key='thread'),0,'71000000-0000-4000-8000-000000000001','Explain my sensor prototype.') IS NOT NULL FROM f) AND (SELECT count(*)=1 FROM ai_messages WHERE conversation_id=(SELECT id FROM ids WHERE key='thread')));
SELECT pg_temp.reject('stale context updates are rejected',$q$SELECT append_ai_message(owner,(SELECT id FROM ids WHERE key='thread'),0,gen_random_uuid(),'Stale') FROM f$q$,'revision conflict');
SELECT set_ai_sharing(owner,(SELECT id FROM ids WHERE key='thread'),1,true) FROM f;
SELECT pg_temp.ok('explicit sharing makes the thread readable by teammates',(SELECT jsonb_array_length(read_ai_conversation(teammate,(SELECT id FROM ids WHERE key='thread')))=1 FROM f));
SELECT pg_temp.reject('sharing does not transfer authorship',$q$SELECT append_ai_message(teammate,(SELECT id FROM ids WHERE key='thread'),2,gen_random_uuid(),'Wrong author') FROM f$q$,'owner required');
SELECT pg_temp.reject('outsider still cannot read shared thread',$q$SELECT read_ai_conversation(outsider,(SELECT id FROM ids WHERE key='thread')) FROM f$q$,'access denied');
INSERT INTO ids SELECT 'pin1',pin_ai_conversation(owner,(SELECT id FROM ids WHERE key='thread'),2,'Saved explanation') FROM f;
SELECT pg_temp.ok('pin retry produces one snapshot',(SELECT pin_ai_conversation(owner,(SELECT id FROM ids WHERE key='thread'),2,'Saved explanation')=(SELECT id FROM ids WHERE key='pin1') FROM f));
SELECT append_ai_message(owner,(SELECT id FROM ids WHERE key='thread'),2,gen_random_uuid(),'Now discuss enclosure size.') FROM f;
SELECT pg_temp.ok('conversation continues without changing pinned snapshot',(SELECT jsonb_array_length(read_ai_snapshot(owner,(SELECT id FROM ids WHERE key='pin1'))->'messages')=1 FROM f) AND (SELECT count(*)=2 FROM ai_messages WHERE conversation_id=(SELECT id FROM ids WHERE key='thread')));
SELECT pg_temp.reject('team sharing does not expose private Learning Hub snapshots',$q$SELECT read_ai_snapshot(teammate,(SELECT id FROM ids WHERE key='pin1')) FROM f$q$,'private learning');
INSERT INTO ids SELECT 'pin2',pin_ai_conversation(owner,(SELECT id FROM ids WHERE key='thread'),3,'New snapshot') FROM f;
SELECT pg_temp.ok('later pin captures a separate cutoff',(SELECT id FROM ids WHERE key='pin1')<>(SELECT id FROM ids WHERE key='pin2'));
SELECT pg_temp.ok('Learning Hub saved collection includes the owners AI snapshots',(SELECT jsonb_array_length(read_learning_hub_saved(owner)->'ai_snapshots')=2 AND jsonb_array_length(read_learning_hub_saved(teammate)->'ai_snapshots')=0 FROM f));
INSERT INTO ids SELECT 'chat-job',request_ai_job(owner,(SELECT id FROM ids WHERE key='thread'),3,'71000000-0000-4000-8000-000000000010','CHAT') FROM f;
SELECT pg_temp.ok('job request retry returns the same input snapshot',(SELECT request_ai_job(owner,(SELECT id FROM ids WHERE key='thread'),0,'71000000-0000-4000-8000-000000000010','CHAT')=(SELECT id FROM ids WHERE key='chat-job') FROM f));
SELECT pg_temp.reject('job kind cannot change under a retry key',$q$SELECT request_ai_job(owner,(SELECT id FROM ids WHERE key='thread'),3,'71000000-0000-4000-8000-000000000010','DESIGN') FROM f$q$,'different kind');
CREATE TEMP TABLE chat_claim AS SELECT claim_ai_job('acceptance-worker') AS data;
SELECT pg_temp.reject('wrong worker token cannot complete a job',$q$SELECT complete_ai_job((SELECT id FROM ids WHERE key='chat-job'),gen_random_uuid(),'fixture-model','{"answer":"Wrong worker"}')$q$,'claim conflict');
SELECT complete_ai_job((data->>'id')::uuid,(data->>'claim_token')::uuid,'acceptance-fixture',jsonb_build_object('answer','Fixture response, not a real model call.','suggestions',jsonb_build_array(jsonb_build_object('catalog_key','led_red','name','Red LED','quantity',2,'price',1,'currency',(SELECT currency FROM project_budgets WHERE project_id=(SELECT project FROM f)),'reason','Fixture suggestion')))) FROM chat_claim;
SELECT pg_temp.ok('one successful job creates exactly one assistant reply',(SELECT count(*)=1 FROM ai_messages WHERE job_id=(SELECT id FROM ids WHERE key='chat-job')));
SELECT pg_temp.reject('completed job cannot be completed twice',$q$SELECT complete_ai_job((data->>'id')::uuid,(data->>'claim_token')::uuid,'acceptance-fixture','{"answer":"Duplicate"}') FROM chat_claim$q$,'claim conflict');
SELECT pg_temp.reject('finished model result is immutable',$q$UPDATE ai_jobs SET result='{}' WHERE id=(SELECT id FROM ids WHERE key='chat-job')$q$,'immutable');
SELECT pg_temp.ok('job output is scoped to permitted readers',(SELECT read_ai_job(teammate,(SELECT id FROM ids WHERE key='chat-job'))->>'status'='SUCCEEDED' FROM f));
SELECT pg_temp.reject('job result rejects foreign students',$q$SELECT read_ai_job(outsider,(SELECT id FROM ids WHERE key='chat-job')) FROM f$q$,'access denied');
INSERT INTO ids SELECT 'suggestion',id FROM ai_part_suggestions WHERE job_id=(SELECT id FROM ids WHERE key='chat-job');
SELECT pg_temp.reject('foreign BOM cannot bind a private cross-project AI suggestion',$q$INSERT INTO project_bom_items(project_id,name,quantity_required,created_by,updated_by,ai_suggestion_id) SELECT (SELECT project_id FROM project_students WHERE student_id=f.outsider AND left_at IS NULL LIMIT 1),'Wrong source',1,f.outsider,f.outsider,(SELECT id FROM ids WHERE key='suggestion') FROM f$q$,'suggestion access denied');
INSERT INTO ids SELECT 'bom',apply_ai_suggestion(owner,(SELECT id FROM ids WHERE key='suggestion'),project) FROM f;
SELECT pg_temp.reject('adopted AI suggestion provenance cannot be removed',$q$UPDATE project_bom_items SET ai_suggestion_id=NULL,updated_by=(SELECT owner FROM f) WHERE id=(SELECT id FROM ids WHERE key='bom')$q$,'provenance');
SELECT pg_temp.ok('adopting suggestion twice creates one BOM entry',(SELECT apply_ai_suggestion(owner,(SELECT id FROM ids WHERE key='suggestion'),project)=(SELECT id FROM ids WHERE key='bom') FROM f));
SELECT pg_temp.reject('foreign student cannot adopt into another project',$q$SELECT apply_ai_suggestion(outsider,(SELECT id FROM ids WHERE key='suggestion'),project) FROM f$q$,'own project');
INSERT INTO ids SELECT 'design-job',request_ai_job(owner,(SELECT id FROM ids WHERE key='thread'),(SELECT revision FROM ai_conversations WHERE id=(SELECT id FROM ids WHERE key='thread')),gen_random_uuid(),'DESIGN') FROM f;
CREATE TEMP TABLE design_claim AS SELECT claim_ai_job('acceptance-design-worker') AS data;
SELECT pg_temp.reject('design requires a real ready image reference',$q$SELECT complete_ai_job((data->>'id')::uuid,(data->>'claim_token')::uuid,'fixture-model','{"answer":"Design","design":{"length_mm":200,"width_mm":120,"height_mm":90,"method":"Fixture","assumptions":[]}}') FROM design_claim$q$,'owned ready image');
INSERT INTO files(id,uploaded_by,storage_key,original_name,mime_type,byte_size,sha256,status) SELECT '71000000-0000-4000-8000-000000000090',owner,'acceptance/design-image','design.png','image/png',80,repeat('d',64),'READY' FROM f;
SELECT complete_ai_job((data->>'id')::uuid,(data->>'claim_token')::uuid,'acceptance-fixture','{"answer":"Fixture design result","design":{"image_file_id":"71000000-0000-4000-8000-000000000090","length_mm":200,"width_mm":120,"height_mm":90,"method":"Fixture bounding-box estimate","assumptions":["Estimated enclosure clearance"]}}') FROM design_claim;
SELECT pg_temp.ok('dimensions are numeric millimetres with an explicit estimated basis',(SELECT length_mm=200 AND width_mm=120 AND height_mm=90 AND is_estimate AND length(sizing_method)>0 FROM ai_project_designs WHERE job_id=(SELECT id FROM ids WHERE key='design-job')));
SELECT pg_temp.reject('generated design history cannot be overwritten',$q$UPDATE ai_project_designs SET length_mm=500 WHERE job_id=(SELECT id FROM ids WHERE key='design-job')$q$,'immutable');
SELECT pg_temp.ok('model sources are never automatically marked verified',NOT EXISTS(SELECT 1 FROM ai_sources WHERE verified_at IS NOT NULL));
ROLLBACK;
